#expApp .hist-thumb {
  width: 40px;
  height: 32px;
  margin: 0 auto;
  border: 2px solid #B8D9BE;
  border-radius: 6px;
  object-fit: cover;
  cursor: zoom-in;
  transition: .15s ease;
}

