#expApp .table-scroll::-webkit-scrollbar,
#expApp .scards-all::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

#expApp .table-scroll::-webkit-scrollbar-track,
#expApp .scards-all::-webkit-scrollbar-track { background: var(--life-green-50); }

#expApp .table-scroll::-webkit-scrollbar-thumb,
#expApp .scards-all::-webkit-scrollbar-thumb {
  border: 2px solid var(--life-green-50);
  border-radius: 99px;
  background: #8FBD97;
