#expApp .pgrid .staff-combo-input {
  width: 100%;
  min-height: 40px;
  padding: 8px 40px 8px 10px;
  border: 1.5px solid var(--life-border);
  border-radius: 9px;
  outline: none;
  background-color: #fff;
  background-image:
