    linear-gradient(135deg, var(--life-green-700) 50%, transparent 50%);
  background-position:
    calc(100% - 18px) 17px,
    calc(100% - 12px) 17px;
  background-size: 6px 6px, 6px 6px;
  background-repeat: no-repeat;
  color: var(--life-text);
  font-size: 12.5px;
  cursor: text;
  box-sizing: border-box;
}

#expApp .pgrid .staff-combo-input:focus {
  border-color: var(--life-green-500);
  box-shadow: 0 0 0 3px rgba(67,160,71,.12);
}

#expApp .pgrid .staff-combo-input:disabled {
  background-color: #F4F8F5;
  color: #8C9A8F;
  cursor: not-allowed;
  opacity: 1;
}

#expApp .pgrid .staff-combo-input::placeholder { color: #7D8F82; opacity: 1; }

#expApp .pgrid .staff-combo-input.ferr {
  border-color: var(--life-red) !important;
  box-shadow: 0 0 0 3px rgba(198,40,40,.12) !important;
}

