@media (max-width: 1180px) {
  #expApp .life-exp-hero { align-items: flex-start; flex-direction: column; }
  #expApp .life-exp-header-status { width: 100%; justify-content: flex-start; }
  #expApp .topfilter { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  #expApp .filter-actions { align-self: end; }
  #expApp .scards-primary { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  #expApp .scards-all { grid-template-columns: repeat(5, minmax(230px, 1fr)); }
  #expApp .pgrid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 760px) {
  #expApp { width: calc(100vw - 16px); margin-top: 6px; }
  #expApp .life-exp-hero { padding: 15px; border-radius: 0 0 14px 14px; }
  #expApp .life-exp-brand { align-items: flex-start; }
  #expApp .life-exp-logo { width: 56px; min-width: 56px; height: 56px; }
  #expApp .life-exp-logo-letter { font-size: 32px; }
  #expApp .life-exp-brand-copy h1 { font-size: 15px; }
  #expApp .life-exp-brand-copy p { font-size: 9px; letter-spacing: 1.5px; }
  #expApp .life-section-head h2 { font-size: 13.5px; }
  #expApp .life-panel { padding: 13px 12px; }
  #expApp .topfilter,
  #expApp .scards-primary,
  #expApp .scards-secondary,
  #expApp .entry-head-fields,
  #expApp .pgrid { grid-template-columns: 1fr; }
  #expApp .scards-all { grid-template-columns: repeat(5, minmax(220px, 1fr)); }
  #expApp .scards-all .scard { min-width: 220px; }
  #expApp .filter-actions,
  #expApp .acts { width: 100%; }
  #expApp .filterbtn,
  #expApp .resetbtn,
  #expApp .bdraft,
  #expApp .bsubmit { flex: 1; }
  #expApp .staff-searchbar { align-items: stretch; flex-direction: column; }
  #expApp .history-actions { width: 100%; justify-content: space-between; }
}

@media (max-width: 480px) {
  #expApp .life-exp-brand { flex-direction: column; }
  #expApp .life-exp-header-status,
  #expApp .life-exp-branch-pill,
  #expApp .life-exp-clock-pill { width: 100%; }
  #expApp .life-exp-clock-pill { align-items: flex-start; }
  #expApp .filter-actions,
  #expApp .acts,
  #expApp .entry-status-wrap { flex-direction: column; }
  #expApp .filterbtn,
  #expApp .resetbtn,
  #expApp .bdraft,
  #expApp .bsubmit,
  #expApp .eno,
  #expApp .esp { width: 100%; text-align: center; }
}

