   el('.jv-erp-link').href='/app/journal-entry/'+encodeURIComponent(data.name);el('.jv-date-controls').hidden=!data.can_edit_date;el('.jv-date-controls').style.display=data.can_edit_date?'flex':'none';el('.jv-new-date').value=data.posting_date;el('.jv-new-date').max=data.today;
